int fd_file = open("output.txt", O_WRONLY | O_CREAT);
int stdout_fd = STDOUT_FILENO; // Usually 1

// Check if open() succeeded
if (fd_file != -1) {

    // Duplicate fd_file onto stdout_fd (1).
    // If stdout_fd was open, it is closed first.
    int result = dup2(fd_file, stdout_fd);

    if (result == -1) {
        // Handle EBADF or EMFILE
    }

    // After success: Writes to STDOUT_FILENO now write to output.txt
    close(fd_file); // Not needed anymore; descriptor 1 handles the I/O
}

// Common technique: Saving original FD before redirection
int original_stdout = dup(STDOUT_FILENO);
// ... Perform dup2 redirection here ...
dup2(original_stdout, STDOUT_FILENO); // Restore stdout
close(original_stdout);
